import{_ as a,C as n,o,c as i,E as r,a2 as s}from"./chunks/framework.Cm6XCzck.js";const f=JSON.parse('{"title":"TMPA–FCoP–CodeFlowMu Implementation Case — Draft I0.5","description":"","frontmatter":{"title":"TMPA–FCoP–CodeFlowMu Implementation Case — Draft I0.5","outline":"deep"},"headers":[],"relativePath":"en/publications/implementation-case-i0.5/part-01.md","filePath":"en/publications/implementation-case-i0.5/part-01.md","lastUpdated":1785926126000}'),d={name:"en/publications/implementation-case-i0.5/part-01.md"};function c(l,e,p,u,h,m){const t=n("ArticleCover");return o(),i("div",null,[r(t,{image:"/assets/covers/implementation-case.svg",kicker:"Engineering Case",title:"TMPA Implementation Case",summary:"The S0.4 engineering baseline and a WP-13 multi-agent evidence-gating and fact-checking case.",version:"I0.5",status:"S0.4 engineering evidence draft",languageHref:"/zh/publications/implementation-case-i0.5",languageLabel:"简体中文"}),e[0]||(e[0]=s(`<h1 id="tmpa-implementation-and-case-report" tabindex="-1">TMPA Implementation and Case Report <a class="header-anchor" href="#tmpa-implementation-and-case-report" aria-label="Permalink to &quot;TMPA Implementation and Case Report&quot;">​</a></h1><h2 id="s0-4-reference-reader-fcop-codeflowmu-and-the-wp-13-multi-agent-fact-check" tabindex="-1">S0.4 Reference Reader, FCoP, CodeFlowMu, and the WP-13 Multi-Agent Fact Check <a class="header-anchor" href="#s0-4-reference-reader-fcop-codeflowmu-and-the-wp-13-multi-agent-fact-check" aria-label="Permalink to &quot;S0.4 Reference Reader, FCoP, CodeFlowMu, and the WP-13 Multi-Agent Fact Check&quot;">​</a></h2><blockquote><p><strong>Document Version:</strong> Draft I0.5<br><strong>Status:</strong> Author-Produced Implementation and Case Report<br><strong>Normative Target:</strong> TMPA Core S0.4<br><strong>Historical Evidence Baseline:</strong> I0.3 / S0.3 corpus<br><strong>Report and Execution Date:</strong> 2026-08-03; WP-13 case observed 2026-08-05<br><strong>Conformance Corpus:</strong> <code>tmpa-s0.4-fcop-codeflowmu-20260803</code><br><strong>Authority Boundary:</strong> This report is evidentiary and non-normative. TMPA Core requirements are defined only by the GitHub Core Specification.</p></blockquote><h2 id="abstract" tabindex="-1">Abstract <a class="header-anchor" href="#abstract" aria-label="Permalink to &quot;Abstract&quot;">​</a></h2><p>This report advances the implementation case from an unavailable S0.3-era archive to a public, executable S0.4 corpus. I0.5 retains the I0.4 Reference Reader, C01–C14 fixtures, manifests, result envelopes, product-evidence assertions, and one-command runner, and adds the WP-13 field case. In that case, a subexecution produced a completion-meaning claim without confirmed exit status, tests, commit, or formal report. PM withheld release on persistent facts; DEV then completed the same task after tool recovery, followed by role-separated QA.</p><p>The FCoP protocol defines a project-visible coordination profile in which routed textual artifacts, lifecycle paths, atomic rename, append-only transition evidence, role bindings, reviews, issues, alerts, and inspection reports remain available outside transient sessions. Its reference implementation provides bounded executable evidence for those rules. CodeFlowMu adopts the protocol for persistent work identities, task/report flows, review gates, dependency waiting, recovery, and archival history. XiaoDian AI contributes pre-specification field evidence from a governed NL2SQL pipeline, including retained pass and rejection paths.</p><p>The S0.4 Reference Reader reports <strong>14 PASS</strong> against its author-produced synthetic fixture suite. The separately evaluated FCoP–CodeFlowMu product baseline remains <strong>1 PASS, 9 PARTIAL, 4 NOT RUN, and 0 FAIL</strong>, with aggregate verdict <code>PARTIAL</code>. WP-13 strengthens author-produced <code>demonstrated</code> evidence related to C04, C06, C07, and C13, but it did not execute a new S0.4 product-reader criterion. The verdicts are therefore not relabeled, and no independent-validation claim is made.</p><h1 id="_1-scope-and-evidence-boundary" tabindex="-1">1. Scope and Evidence Boundary <a class="header-anchor" href="#_1-scope-and-evidence-boundary" aria-label="Permalink to &quot;1. Scope and Evidence Boundary&quot;">​</a></h1><p>This report asks what the S0.4 Reference Reader implements, what the fixed product evidence demonstrates, and which S0.4 product requirements remained unexecuted. It is evidentiary and nonnormative. Its verdicts are preserved against the historical S0.4 target; the current <a href="/joinwell52/en/publications/tmpa-core-specification-s0.5">TMPA Core Specification S0.5</a> defines current requirements and canonical test meanings, and I0.5 does not claim S0.5 conformance. The <a href="/joinwell52/en/publications/tmpa-architecture-paper-a0.5">Architecture Paper A0.5</a> explains the theory.</p><p>Evidence classes remain <strong>specified</strong>, <strong>implemented</strong>, <strong>demonstrated</strong>, and <strong>independently adopted</strong>. The Reference Reader is implemented and author-demonstrated. The product baseline contains mixed implemented/demonstrated evidence and remains <code>PARTIAL</code>. Fixture success is not converted into FCoP or CodeFlowMu product conformance, and no independent-adoption or independent-validation claim is made.</p><h1 id="_2-engineering-lineage-and-component-boundaries" tabindex="-1">2. Engineering Lineage and Component Boundaries <a class="header-anchor" href="#_2-engineering-lineage-and-component-boundaries" aria-label="Permalink to &quot;2. Engineering Lineage and Component Boundaries&quot;">​</a></h1><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CURRENT CONCEPTUAL LAYERING</span></span>
<span class="line"><span>TMPA architecture → reusable FCoP protocol profile → CodeFlowMu and other applications</span></span>
<span class="line"><span></span></span>
<span class="line"><span>HISTORICAL LINEAGE</span></span>
<span class="line"><span>XiaoDian AI practice → original TMPA → FCoP extraction and maturation</span></span>
<span class="line"><span>                    → CodeFlowMu application → current TMPA formalization</span></span></code></pre></div><p>FCoP defines a protocol profile over a file-based subset of TMPA semantics. The <code>fcop</code> and <code>fcop-mcp</code> packages are its reference implementation; CodeFlowMu is a downstream application that adopts the protocol as coordination and governance infrastructure. FCoP does not exhaust TMPA; CodeFlowMu does not define FCoP; XiaoDian AI is lineage and field evidence rather than a product-level TMPA reader.</p><p>Terminology follows Section 2 of the Core Specification. In particular, <strong>governance object</strong> is a semantic unit, <strong>source artifact</strong> is a physical observation, <strong>governance reader</strong> is the deterministic reconstruction stage, and <code>valid</code> / <code>invalid</code> / <code>undetermined</code> are the only semantic governance judgments. This report does not introduce alternative meanings.</p><p>FCoP uses ordinary filesystem artifacts and operating-system operations as a project-visible coordination surface. CodeFlowMu combines FCoP operations with agent sessions, runtime scheduling, role interfaces, business workflows, approval paths, recovery controls, and user-facing views. XiaoDian AI contributes permission, validation, NL2SQL, policy-gate, rejection, and audit evidence.</p><h1 id="_3-fcop-protocol-and-reference-implementation-evidence" tabindex="-1">3. FCoP Protocol and Reference-Implementation Evidence <a class="header-anchor" href="#_3-fcop-protocol-and-reference-implementation-evidence" aria-label="Permalink to &quot;3. FCoP Protocol and Reference-Implementation Evidence&quot;">​</a></h1><h2 id="_3-1-durable-textual-message-and-state-surface" tabindex="-1">3.1 Durable Textual Message and State Surface <a class="header-anchor" href="#_3-1-durable-textual-message-and-state-surface" aria-label="Permalink to &quot;3.1 Durable Textual Message and State Surface&quot;">​</a></h2><p>FCoP treats the project filesystem as a durable textual message and state surface: <strong>files carry protocol, paths address state, and events replay transitions</strong>. A routed <code>TASK-*</code> artifact serves as a stable work anchor; reports, reviews, issues, alerts, and decisions are separate linked artifacts; filenames carry routing metadata; lifecycle directories expose current state; atomic rename performs lifecycle movement; transition evidence records how state was reached; and artifacts remain inspectable after the originating session ends.</p><h2 id="_3-2-agent-visible-role-binding" tabindex="-1">3.2 Agent-Visible Role Binding <a class="header-anchor" href="#_3-2-agent-visible-role-binding" aria-label="Permalink to &quot;3.2 Agent-Visible Role Binding&quot;">​</a></h2><p>Governed participation begins with an explicit role binding visible to the agent. It identifies active role, collaboration context, scope, permitted/prohibited actions, and independent review or escalation roles. This is operational protocol identity, not cryptographic or legal identity.</p><h2 id="_3-3-lifecycle" tabindex="-1">3.3 Lifecycle <a class="header-anchor" href="#_3-3-lifecycle" aria-label="Permalink to &quot;3.3 Lifecycle&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>inbox → active → review → done → archive → history</span></span>
<span class="line"><span>           ↑        |</span></span>
<span class="line"><span>           └─ reject┘</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Action</th><th>Source</th><th>Target</th><th>Typical authority</th></tr></thead><tbody><tr><td><code>create_task</code></td><td>—</td><td><code>inbox</code></td><td>task creator</td></tr><tr><td><code>claim_task</code></td><td><code>inbox</code></td><td><code>active</code></td><td>assigned executor</td></tr><tr><td><code>submit_task</code></td><td><code>active</code></td><td><code>review</code></td><td>responsible executor</td></tr><tr><td><code>approve_task</code></td><td><code>review</code></td><td><code>done</code></td><td>reviewer or approver</td></tr><tr><td><code>reject_task</code></td><td><code>review</code></td><td><code>active</code></td><td>reviewer</td></tr><tr><td><code>finish_task</code></td><td><code>active</code></td><td><code>done</code></td><td>profile-authorized role</td></tr><tr><td><code>archive_task</code></td><td><code>done</code></td><td><code>archive</code></td><td>archival authority</td></tr><tr><td><code>archive_to_history</code></td><td><code>archive</code></td><td><code>history/...</code></td><td>archival authority</td></tr></tbody></table><p>Path represents current state under the profile; transition evidence records history. Inconsistency is an issue, not silently repaired state.</p><h2 id="_3-4-routing-atomic-publication-and-recovery" tabindex="-1">3.4 Routing, Atomic Publication, and Recovery <a class="header-anchor" href="#_3-4-routing-atomic-publication-and-recovery" aria-label="Permalink to &quot;3.4 Routing, Atomic Publication, and Recovery&quot;">​</a></h2><p>A reference filename is <code>{TYPE}-{YYYYMMDD}-{NNN}-{SENDER}-to-{RECIPIENT}(-slug).md</code>. Filename is transport envelope; body and schema carry complete meaning. Atomic publication uses write-to-temporary and rename where supported. Recovery reconstructs task identity, current lifecycle, responsibility, linked evidence, unresolved dependencies, and issues from persistent artifacts rather than hidden session context.</p>`,26))])}const v=a(d,[["render",c]]);export{f as __pageData,v as default};
